# R survey::rake / postStratify reference for Pulse.Rake (internal/rake,
# survey-tables E4-S1). Never run by CI: the generated Go file is the
# oracle. Needs R 4.6.1 and the survey package (4.5).
#
# Usage (from this directory):
#   Rscript gen_rake_reference.R
#   gofmt -w ../reference_values_test.go
#
# Writes ../reference_values_test.go: a 120-record sample (age x gender x
# region x wave + a design weight, drawn once from a fixed seed and
# written verbatim, so Go never re-draws it) and, per case, every
# record's weight normalised to sum to the record count (per wave under
# `by`). Raking runs to epsilon 1e-13 within 10,000 iterations, so the
# fixed point is compared, not a sweep count.
#   rim3       survey::rake to age 29/33/38, gender 51/49, region 17/21/38/24
#   rim3_base  the same, starting from the design weight
#   cell       survey::postStratify to a joint age x gender table
#   by_wave    rim3 on each wave separately
suppressPackageStartupMessages(library(survey))
want <- "4.6.1"
have <- sprintf("%s.%s", R.version$major, R.version$minor)
if (have != want) stop(sprintf("R %s required, found %s", want, have))

set.seed(20261016)
n <- 120
ages <- c("18-34", "35-54", "55+")
genders <- c("F", "M")
regions <- c("NE", "MW", "S", "W")
df <- data.frame(
  age = factor(sample(ages, n, replace = TRUE, prob = c(0.2, 0.35, 0.45)), levels = ages),
  gender = factor(sample(genders, n, replace = TRUE, prob = c(0.6, 0.4)), levels = genders),
  region = factor(sample(regions, n, replace = TRUE, prob = c(0.25, 0.25, 0.3, 0.2)), levels = regions),
  wave = sample(1:2, n, replace = TRUE),
  dw = round(runif(n, 0.5, 2.0), 3)
)

targets <- list(
  age = c("18-34" = 29, "35-54" = 33, "55+" = 38),
  gender = c(F = 51, M = 49),
  region = c(NE = 17, MW = 21, S = 38, W = 24)
)
ctl <- list(maxit = 10000, epsilon = 1e-13, verbose = FALSE)

rim <- function(d, wcol) {
  m <- nrow(d)
  des <- if (is.null(wcol)) svydesign(ids = ~1, weights = rep(1, m), data = d)
         else svydesign(ids = ~1, weights = d[[wcol]], data = d)
  pops <- lapply(names(targets), function(v) {
    t <- targets[[v]]
    out <- data.frame(factor(names(t), levels = levels(d[[v]])), Freq = t / sum(t) * m)
    names(out)[1] <- v
    out
  })
  r <- rake(des, list(~age, ~gender, ~region), pops, control = ctl)
  w <- weights(r)
  w / sum(w) * m
}

cellT <- expand.grid(age = ages, gender = genders, stringsAsFactors = FALSE)
cellT$share <- c(0.14, 0.16, 0.20, 0.15, 0.17, 0.18)
cell <- function(d) {
  m <- nrow(d)
  des <- svydesign(ids = ~1, weights = rep(1, m), data = d)
  pop <- data.frame(age = factor(cellT$age, levels = ages), gender = factor(cellT$gender, levels = genders),
                    Freq = cellT$share * m)
  ps <- postStratify(des, ~age + gender, pop)
  w <- weights(ps)
  w / sum(w) * m
}

byw <- numeric(n)
for (g in sort(unique(df$wave))) {
  idx <- which(df$wave == g)
  byw[idx] <- rim(df[idx, ], NULL)
}

cases <- list(
  rim3 = rim(df, NULL),
  rim3_base = rim(df, "dw"),
  cell = cell(df),
  by_wave = byw
)

num <- function(x) sprintf("%.17g", x)
lines <- c(
  "// Code generated by testdata/gen_rake_reference.R; DO NOT EDIT.",
  sprintf("// R %s, survey %s.", have, as.character(packageVersion("survey"))),
  "",
  "package rake",
  "",
  "// refRow is one record of the reference sample.",
  "type refRow struct {",
  "\tage, gender, region string",
  "\twave                uint64",
  "\tdw                  float64",
  "}",
  "",
  "var refRows = []refRow{"
)
for (i in seq_len(n)) {
  lines <- c(lines, sprintf("\t{%s, %s, %s, %d, %s},", deparse(as.character(df$age[i])),
    deparse(as.character(df$gender[i])), deparse(as.character(df$region[i])), df$wave[i], num(df$dw[i])))
}
lines <- c(lines, "}", "", "// refCellShares is the cell case's joint age x gender table.",
  "var refCellShares = []struct {", "\tage, gender string", "\tshare       float64", "}{")
for (k in seq_len(nrow(cellT))) {
  lines <- c(lines, sprintf("\t{%s, %s, %s},", deparse(cellT$age[k]), deparse(cellT$gender[k]), num(cellT$share[k])))
}
lines <- c(lines, "}", "", "// refWeights holds each case's per-record weights (sum = record count).",
  "var refWeights = map[string][]float64{")
for (nm in names(cases)) {
  lines <- c(lines, sprintf("\t%s: {", deparse(nm)))
  w <- cases[[nm]]
  for (s in seq(1, n, by = 4)) {
    lines <- c(lines, paste0("\t\t", paste(sapply(w[s:min(n, s + 3)], num), collapse = ", "), ","))
  }
  lines <- c(lines, "\t},")
}
lines <- c(lines, "}")
writeLines(lines, file.path("..", "reference_values_test.go"))
message("wrote ../reference_values_test.go")
